package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
@WebServlet("/addProblem") public class AddProblemServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.html");return;}String sql="INSERT INTO problems(user_id,title,category,location,description,priority) VALUES(?,?,?,?,?,?)";try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement(sql)){q.setInt(1,(Integer)h.getAttribute("userId"));q.setString(2,r.getParameter("title"));q.setString(3,r.getParameter("category"));q.setString(4,r.getParameter("location"));q.setString(5,r.getParameter("description"));q.setString(6,r.getParameter("priority"));q.executeUpdate();s.sendRedirect("view-problems?success=added");}catch(Exception e){e.printStackTrace();s.sendRedirect("add-problem.jsp?error=database");}}}
